const conductor = document.getElementById('conductor');
const emfDisplay = document.getElementById('emfDisplay');
const lengthSlider = document.getElementById('lengthSlider');
const fieldSlider = document.getElementById('fieldSlider');
const lengthValue = document.getElementById('lengthValue');
const fieldValue = document.getElementById('fieldValue');
const speedValue = document.getElementById('speedValue');
const speedBar = document.getElementById('speedBar');
const calcB = document.getElementById('calcB');
const calcL = document.getElementById('calcL');
const calcV = document.getElementById('calcV');
const calcResult = document.getElementById('calcResult');

let isDragging = false;
let conductorX = 120; // 初始位置（像素）
let velocity = 0; // 速度
let lastX = 0;
let L = 0.5; // 导体长度
let B = 0.4; // 磁场强度

// 鼠标拖动
conductor.addEventListener('mousedown', (e) => {
    isDragging = true;
    lastX = e.clientX;
    conductor.style.cursor = 'grabbing';
});

document.addEventListener('mousemove', (e) => {
    if (!isDragging) return;

    const dx = e.clientX - lastX;
    conductorX += dx;
    conductorX = Math.max(0, Math.min(240, conductorX));
    conductor.style.transform = `translateX(${conductorX}px)`;

    velocity = dx * 2; // 速度与位移成正比
    lastX = e.clientX;

    updateCalculation();
});

document.addEventListener('mouseup', () => {
    if (isDragging) {
        isDragging = false;
        conductor.style.cursor = 'grab';
    }
});

// 滑块控制
lengthSlider.addEventListener('input', () => {
    L = parseFloat(lengthSlider.value);
    lengthValue.textContent = L.toFixed(1);
    calcL.textContent = L.toFixed(1);
    updateCalculation();
});

fieldSlider.addEventListener('input', () => {
    B = parseFloat(fieldSlider.value);
    fieldValue.textContent = B.toFixed(1);
    calcB.textContent = B.toFixed(1);
    updateCalculation();
});

function updateCalculation() {
    // 速度（m/s），假设50px = 1m/s
    const v = Math.abs(velocity);

    // 计算电动势 E = B * L * v
    const E = B * L * v;

    // 更新显示
    emfDisplay.textContent = E.toFixed(2);
