let conductorX = 120; // 初始位置（像素）
let velocity = 0; // 速度
let lastX = 0;
let L = 0.5; // 导体长度
let B = 0.4; // 磁场强度

// 鼠标拖动
conductor.addEventListener('mousedown', (e) => {
    isDragging = true;
    lastX = e.clientX;
    conductor.style.cursor = 'grabbing';
});

document.addEventListener('mousemove', (e) => {
    if (!isDragging) return;

    const dx = e.clientX - lastX;
    conductorX += dx;
    conductorX = Math.max(0, Math.min(240, conductorX));
    conductor.style.transform = `translateX(${conductorX}px)`;

    velocity = dx * 2; // 速度与位移成正比
    lastX = e.clientX;

    updateCalculation();
});

document.addEventListener('mouseup', () => {
    if (isDragging) {
        isDragging = false;
        conductor.style.cursor = 'grab';
    }
});

